'use strict';

// Спектр песни mainmenu.mp3 для анализатора на горизонте: 20 кадров в секунду,
// в каждом кадре 24 полосы от 40 Гц до 14 кГц (по логарифму), уровень 0–z.
// Каждая полоса нормирована отдельно, чтобы и бас, и верха двигались заметно.
const MAINMENU_SPECTRUM = {
  fps: 20,
  bands: 24,
  frames: 4400,
  data: '',
  // уровни всех полос (0–1) в момент t, с плавной интерполяцией между кадрами
  at(t, out) {
    const x = t * this.fps;
    const i = Math.max(0, Math.min(this.frames - 2, Math.floor(x)));
    const k = Math.max(0, Math.min(1, x - i));
    for (let b = 0; b < this.bands; b++) {
      const a = parseInt(this.data[i * this.bands + b], 36);
      const c = parseInt(this.data[(i + 1) * this.bands + b], 36);
      out[b] = (a + (c - a) * k) / 35;
    }
    return out;
  },
};
